// The break-glass admin token (P2-09, THREAT_MODEL T1): `ab_admin_<43 base62>_<6 base62>`, generated by
// `agility-bridge admin-token`, given to the server as `AB_ADMIN_TOKEN` or `AB_ADMIN_TOKEN_FILE`. Anything else is
// refused at boot (no hand-made or weak values); the server keeps only its SHA-256 and compares in constant time.
import { timingSafeEqual } from '../secrets/keyring.ts';
import { hashDeviceToken, isTypedToken, randomTypedToken } from './device.ts';

const PREFIX = 'ab_admin';

export function generateAdminToken(): string {
  return randomTypedToken(PREFIX).token;
}

export function isWellFormedAdminToken(text: unknown): boolean {
  return isTypedToken(text, PREFIX);
}

/** Holds the digest of the configured admin token and checks presented ones. */
export class AdminTokenVerifier {
  readonly #digest: string;

  private constructor(digest: string) {
    this.#digest = digest;
  }

  /** Refuses anything `agility-bridge admin-token` did not generate. The error never contains the value. */
  static async create(token: string): Promise<AdminTokenVerifier> {
    const value = token.trim();
    if (!isWellFormedAdminToken(value)) {
      throw new TypeError(
        'The admin token must be one generated by `agility-bridge admin-token` (ab_admin_…); hand-made values are refused.',
      );
    }
    return new AdminTokenVerifier(await hashDeviceToken(value));
  }

  async verify(presented: string | null): Promise<boolean> {
    if (presented === null || !isWellFormedAdminToken(presented)) return false;
    return timingSafeEqual(await hashDeviceToken(presented), this.#digest);
  }
}
